tools.example:
h = 0:1000:20000;
[T, a, P, rho] = atmoscoesa(h);
plot(rho, h/1000); xlabel("Density (kg/m^3)"); ylabel("Altitude (km)")

p = lla2ecef([45 10 400e3]);
[gx, gy, gz] = gravitysphericalharmonic(p, "EGM2008", 120);
norm([gx gy gz])

jd = juliandate(2025, 3, 20);
[r, v] = planetEphemeris(jd, "Earth", "Moon");
norm(r)      % Earth-Moon distance in km

yaw = deg2rad(30); pitch = deg2rad(5); roll = deg2rad(-10);
C_bn = angle2dcm(yaw, pitch, roll);        % NED -> body
v_body = C_bn * [100; 0; 0];

q = quatnormalize([0.98 0.05 0.1 0.15]);
[yaw, pitch, roll] = quat2angle(q);
rad2deg([yaw pitch roll])

q = angle2quat(0.2, 0.1, 0);
C = quat2dcm(q);
v_body = C * [0; 0; 9.81];

q1 = angle2quat(pi/4, 0, 0);
q2 = angle2quat(0, pi/8, 0);
q12 = quatmultiply(q1, q2);
quatnorm(q12)     % 1

p = angle2quat(0, 0, 0); q = angle2quat(pi/2, 0, 0);
f = linspace(0, 1, 5)';
qi = quatinterp(repmat(p,5,1), repmat(q,5,1), f, "slerp");
[yaw, ~, ~] = quat2angle(qi); rad2deg(yaw)'

tle = tleread("leoSatelliteConstellation.tle");
t = datetime(2022,1,3,12,0,0) + minutes(0:10:90);
[r, v] = propagateOrbit(t, tle(1));
size(r)     % 3-by-numTimes

ac = fixedWingAircraft("Trainer", 16.2, 11, 1.5);
ac = setCoefficient(ac, ["CD" "CL" "Cm"], ["Zero" "Alpha" "Alpha"], [0.027 4.41 -0.613]);
state = Aero.FixedWing.State("Mass", 1100, "Airspeed", 55);
[F, M] = forcesAndMoments(ac, state)

h = Aero.Animation;
idx = createBody(h, "pa24-250_orange.ac", "Ac3d");
load simdata      % simdata = [t x y z phi theta psi]
h.Bodies{idx}.TimeSeriesSourceType = "Array6DoF";
h.Bodies{idx}.TimeSeriesSource = simdata;
show(h); play(h)

aero = datcomimport("astdatcom.out", true, 0);
alpha = aero{1}.alpha; cl = aero{1}.cl;
plot(alpha, cl(:,1))
